        WeaponInnateSkill skill = (WeaponInnateSkill)this.createSkill(RegisterName, constructor, builder);
        if (item != null && style != null) {
            this.ItemStyleInnateRegister.computeIfAbsent(item, k -> Maps.newHashMap()).put(style, skill);
        }
        this.MaidSkillRegister.put(RegisterName, skill);
    }

    public <S extends WeaponInnateSkill, B extends MaidSkillBuilder<?>> void build(ResourceLocation RegisterName, Function<B, S> constructor, B builder, WeaponCategory category, Style style) {
        WeaponInnateSkill skill = (WeaponInnateSkill)this.createSkill(RegisterName, constructor, builder);
        if (category != null && style != null) {
            this.CategoryStyleInnateRegister.computeIfAbsent(category, k -> Maps.newHashMap()).put(style, skill);
        }
        this.MaidSkillRegister.put(RegisterName, skill);
    }

    private <S extends MaidSkill, B extends MaidSkillBuilder<?>> S createSkill(ResourceLocation RegisterName, Function<B, S> constructor, B builder) {
        builder.setRegistryName(RegisterName);
        ModLoader.get().postEvent(new SkillCreateEvent<B>(builder));
        return (S)((MaidSkill)constructor.apply(builder));
    }

    public static class SkillCreateEvent<B extends MaidSkillBuilder<?>>
    extends GenericEvent<B>
    implements IModBusEvent {
        private final B builder;

        private SkillCreateEvent(B builder) {
            super(builder.getClass());
            this.builder = builder;
        }

        public B getSkillBuilder() {
            return this.builder;
        }
    }
}

